'use strict';
/**
 * Real Chromium visual acceptance pass for the original procedural HO house.
 * Runs against a tiny local static server, with the same CDN import policy
 * as the deployed Micro Mayhem game. No screenshots are generated by AI.
 */
const path=require('node:path');
const fs=require('node:fs');
const http=require('node:http');
const {execFileSync}=require('node:child_process');
const {chromium}=require('playwright-core');

const ROOT=path.resolve(__dirname,'..');
function executable(){
  for(const path of [
    process.env.CHROME_PATH,'/usr/bin/chromium',
    '/usr/bin/google-chrome','/usr/bin/chromium-browser'
  ])if(path&&fs.existsSync(path))return path;
  return execFileSync('which',['chromium'],{encoding:'utf8'}).trim();
}
const types={
  '.js':'text/javascript; charset=utf-8',
  '.html':'text/html; charset=utf-8',
  '.css':'text/css; charset=utf-8',
  '.png':'image/png'
};
const server=http.createServer((req,res)=>{
  let url;
  try{url=new URL(req.url,'http://localhost');}
  catch(e){res.writeHead(400);res.end('Invalid URL');return;}
  const target=path.resolve(ROOT,'.'+decodeURIComponent(url.pathname));
  if(!target.startsWith(ROOT+path.sep)){
    res.writeHead(403);res.end('Forbidden');return;
  }
  fs.stat(target,(error,stat)=>{
    if(error||!stat.isFile()){res.writeHead(404);res.end('Not found');return;}
    res.writeHead(200,{'Content-Type':types[path.extname(target)]||
      'application/octet-stream'});
    fs.createReadStream(target).pipe(res);
  });
});
async function main(){
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const origin='http://127.0.0.1:'+server.address().port;
  const browser=await chromium.launch({
    executablePath:executable(),
    headless:true,
    args:['--no-sandbox','--disable-dev-shm-usage',
      '--enable-unsafe-swiftshader','--use-gl=angle',
      '--use-angle=swiftshader']
  });
  const screenshotDir=path.join(ROOT,'tests','screenshots');
  fs.mkdirSync(screenshotDir,{recursive:true});
  try{
    const page=await browser.newPage({
      viewport:{width:1440,height:900},deviceScaleFactor:1
    });
    const errors=[];
    const shaderErrors=[];
    page.on('pageerror',e=>errors.push(e.message));
    page.on('console',message=>{
      if(message.type()==='error'&&
        /WebGLProgram|Shader Error|ERROR:\s*0:\d+/.test(message.text())){
        shaderErrors.push(message.text());
      }
    });
    page.on('requestfailed',r=>{
      if(/three\.module\.js|ho-hero-house\.js|house-showcase\.js/.test(r.url())){
        errors.push(r.url()+' '+r.failure()?.errorText);
      }
    });
    await page.goto(origin+'/house-showcase.html',
      {waitUntil:'domcontentloaded',timeout:45000});
    try{
      await page.waitForFunction(
        ()=>document.body.dataset.modelReady==='true'&&
          Number(document.body.dataset.renderedFrame||0)>=2,
        null,{timeout:24000});
    }catch(error){
      const diagnostics=await page.evaluate(()=>({
        ready:document.body.dataset.modelReady,
        frames:document.body.dataset.renderedFrame,
        loading:document.getElementById('loading')?.textContent,
        title:document.title,
        canvas:!!document.querySelector('#viewport canvas'),
        readyState:document.readyState,
        scripts:Array.from(document.scripts).map(x=>x.src)
      })).catch(e=>({evaluationError:String(e)}));
      await page.screenshot({
        path:path.join(screenshotDir,'house-hero-debug.png'),
        animations:'disabled',
        timeout:10000
      }).catch(e=>console.error('Could not capture diagnostic screenshot',e.message));
      console.error('HOUSE BOOT DIAGNOSTICS',JSON.stringify({
        ...diagnostics,jsErrors:errors,error:error.message
      }));
      throw error;
    }
    if(errors.length)throw Error('Source load errors: '+errors.join('; '));
    if(await page.locator('#viewport canvas').count()!==1)
      throw Error('Missing live WebGL house canvas');
    const model=await page.evaluate(()=>({
      ready:document.body.dataset.modelReady,
      palette:document.body.dataset.modelPalette,
      seed:document.body.dataset.modelSeed,
      type:document.body.dataset.modelType,
      car:document.body.dataset.modelCar,
      realism:document.body.dataset.modelRealism,
      flocking:Number(document.body.dataset.modelFlocking||0),
      shellSeams:Number(document.body.dataset.modelMoldSeams||0),
      snapFitParts:Number(document.body.dataset.modelSnapParts||0),
      moldedShrubs:Number(document.body.dataset.modelMoldShrubs||0),
      roofClearcoat:Number(document.body.dataset.modelRoofClearcoat),
      wallClearcoat:Number(document.body.dataset.modelWallClearcoat),
      carClearcoat:Number(document.body.dataset.modelCarClearcoat),
      grass:document.getElementById('object-count').textContent
    }));
    if(model.palette!=='sage'||model.seed!=='1407'||
      model.car!=='diecast'||model.flocking<30000||
      !model.realism?.includes('die-cast')||
      !model.realism?.includes('injection molded')||
      model.shellSeams<10||model.snapFitParts<5||
      model.moldedShrubs<8||
      Math.abs(model.roofClearcoat-.08)>.001||
      Math.abs(model.wallClearcoat-.12)>.001||
      Math.abs(model.carClearcoat-.85)>.001||
      Number(model.grass)<30000)throw Error(
        'Unexpected plastic / static-grass / die-cast prototype: '+
        JSON.stringify(model));
    await page.screenshot({
      path:path.join(screenshotDir,'house-hero-desktop.png'),
      animations:'disabled'
    });
    // The house itself stays identical across these four controlled
    // render tests. Camera view and procedural seed must not change.
    const renderModes=[
      ['original','aces','ortho','plain'],
      ['room','neutral','ortho','plain'],
      ['surface','neutral','ortho','micro'],
      ['photo','neutral','perspective','micro']
    ];
    const renderedHashes=new Map();
    for(const [preset,tone,lens,materials] of renderModes){
      await page.locator('[data-render-preset="'+preset+'"]').click();
      await page.waitForFunction(
        expected=>document.body.dataset.renderPreset===expected,
        preset,{timeout:20000}
      );
      const state=await page.evaluate(()=>({
        seed:document.body.dataset.modelSeed,
        palette:document.body.dataset.modelPalette,
        tone:document.body.dataset.renderTone,
        lens:document.body.dataset.renderLens,
        materials:document.body.dataset.renderMaterials,
        dof:document.body.dataset.renderDof,
        effective:document.body.dataset.renderDofEffective
      }));
      if(state.seed!=='1407'||state.palette!=='sage'||
        state.tone!==tone||state.lens!==lens||
        state.materials!==materials)
        throw Error('Rendering preset failed to preserve source model: '+
          JSON.stringify({preset,state}));
      if(preset==='photo'&&state.effective!=='true')
        throw Error('Desktop depth-based photographic lens was not enabled');
      await page.waitForTimeout(350);
      const screenshot=path.join(screenshotDir,
        'house-render-lab-'+preset+'.png');
      await page.locator('#viewport canvas').screenshot({
        path:screenshot,animations:'disabled'
      });
      const crypto=require('node:crypto');
      renderedHashes.set(preset,
        crypto.createHash('sha256').update(fs.readFileSync(screenshot))
          .digest('hex'));
    }
    if(new Set(renderedHashes.values()).size<4){
      throw Error('Some visual rendering presets produced identical canvas files');
    }
    await page.locator('#lab-details summary').click();
    await page.locator('[data-lab-factor="materials"][data-lab-value="plain"]').click();
    if(await page.locator('body').getAttribute('data-render-preset')!=='custom'||
      await page.locator('body').getAttribute('data-render-materials')!=='plain'){
      throw Error('Individual rendering comparison switch did not work');
    }
    await page.locator('[data-render-preset="original"]').click();
    if(shaderErrors.length)throw Error(
      'WebGL shader errors during rendering lab: '+shaderErrors.join('; '));
    console.log('PASS four A/B/C/D render lab presets',
      JSON.stringify(Object.fromEntries(renderedHashes)));
    await page.locator('[data-view="diecast"]').click();
    if(await page.locator('[data-view="diecast"]').getAttribute('aria-pressed')!=='true')
      throw Error('Die-cast model closeup camera failed');
    await page.waitForTimeout(650);
    await page.screenshot({
      path:path.join(screenshotDir,'house-hero-diecast.png'),
      animations:'disabled'
    });
    await page.locator('[data-view="three-quarter"]').click();
    await page.locator('[data-palette="cream"]').click();
    if(await page.locator('body').getAttribute('data-model-palette')!=='cream')
      throw Error('Changing house wall paint failed');
    await page.locator('[data-view="street"]').click();
    await page.locator('[data-view="overhead"]').click();
    if(await page.locator('[data-view="overhead"]').getAttribute('aria-pressed')!=='true')
      throw Error('Camera view control failed');
    await page.locator('#regen').click();
    if(await page.locator('body').getAttribute('data-model-seed')==='1407')
      throw Error('Procedural yard seed did not change');
    await page.locator('#light-switch').click();
    if(await page.locator('#light-switch').getAttribute('aria-pressed')!=='true')
      throw Error('Evening lighting did not switch');
    console.log('PASS desktop procedural house, custom paint, views, regenerated yard, evening light',JSON.stringify(model));
    await page.close();

    const mobile=await browser.newContext({
      viewport:{width:390,height:844},deviceScaleFactor:2,
      isMobile:true,hasTouch:true
    });
    const phone=await mobile.newPage();
    phone.on('pageerror',e=>{throw Error('Mobile JS: '+e.message);});
    await phone.goto(origin+'/house-showcase.html',
      {waitUntil:'domcontentloaded',timeout:45000});
    await phone.waitForFunction(
      ()=>document.body.dataset.modelReady==='true'&&
        Number(document.body.dataset.renderedFrame||0)>=2,
      null,{timeout:45000});
    await phone.screenshot({
      path:path.join(screenshotDir,'house-hero-phone.png'),
      animations:'disabled'
    });
    // Photo preset uses the photographic perspective on phones without
    // the high-cost depth texture pass. Presets remain available by touch.
    await phone.locator('[data-render-preset="photo"]').tap();
    const phonePhoto=await phone.evaluate(()=>({
      preset:document.body.dataset.renderPreset,
      lens:document.body.dataset.renderLens,
      dofEffective:document.body.dataset.renderDofEffective,
      ready:document.body.dataset.modelReady
    }));
    if(phonePhoto.preset!=='photo'||phonePhoto.lens!=='perspective'||
      phonePhoto.dofEffective!=='false'||phonePhoto.ready!=='true'){
      throw Error('Mobile safe photographic rendering fallback failed: '+
        JSON.stringify(phonePhoto));
    }
    await phone.locator('#viewport canvas').screenshot({
      path:path.join(screenshotDir,'house-render-lab-phone-photo.png'),
      animations:'disabled'
    });
    if(await phone.locator('body').getAttribute('data-model-car')!=='diecast'||
      Number(await phone.locator('body').getAttribute('data-model-flocking'))<30000||
      Number(await phone.locator('body').getAttribute('data-model-mold-seams'))<10||
      Number(await phone.locator('body').getAttribute('data-model-snap-parts'))<5)
      throw Error('Mobile rendering lost snap-fit house, die-cast car or grass geometry');
    await phone.locator('[data-palette="blue"]').tap();
    if(await phone.locator('body').getAttribute('data-model-palette')!=='blue')
      throw Error('Phone touch palette control did not work');
    console.log('PASS mobile HO house starts, renders and responds to touch');
    await mobile.close();
  }finally{
    await browser.close();
    await new Promise(resolve=>server.close(resolve));
  }
}
main().then(
  ()=>console.log('PASS procedurally rendered HO house and landscaped yard'),
  e=>{console.error(e.stack||e);process.exitCode=1;}
);
